const MORE = {
  'tyrannosaurus': 'הטירנוזאורוס הוא גם אחד הדינוזאורים הנחקרים ביותר בעולם. חוקרים בדקו את מבנה האוזן הפנימית שלו בסורקים, חישבו את כוח הנשיכה בעזרת מודלים ממוחשבים, ואפילו מצאו עקבות של מחלות בעצמות. ובכל זאת, כל שנה מתפרסם עליו משהו חדש.',
  'triceratops': 'במשך שנים התווכחו חוקרים אם דינוזאור בשם טורוזאורוס, שהיה דומה מאוד לטריצרטופס, הוא בעצם טריצרטופס מבוגר מאוד. רוב החוקרים חושבים היום שמדובר בשני סוגים נפרדים, אבל הוויכוח מלמד כמה קשה לזהות מין מעצמות בלבד.',
  'stegosaurus': 'לסטגוזאורוס היו שיניים קטנות וחלשות יחסית, ולכן חושבים שאכל צמחים רכים ונמוכים — שרכים, טחבים ושיחים. ייתכן שיכול היה להתרומם מעט על הרגליים האחוריות כדי להגיע לענפים גבוהים יותר, אבל זו רק השערה.',
  'brachiosaurus': 'מהברכיוזאורוס עצמו נמצאו פחות עצמות ממה שאפשר לחשוב, ורוב הציורים שלו מבוססים גם על הקרוב האפריקאי שלו. לכן כל מספר על הגובה והמשקל שלו הוא הערכה, ובספרים שונים תמצאו מספרים מעט שונים.',
  'velociraptor': 'השם ולוצירפטור ניתן בשנת 1924, אחרי שמשלחת אמריקאית מצאה במונגוליה גולגולת וטופר. מאז נמצאו ממנו כמה שלדים טובים. בזכות הסרטים הוא אחד הדינוזאורים המפורסמים בעולם, אף שהדמות בסרטים שונה מאוד מהחיה האמיתית.',
  'spinosaurus': 'ממצאים חדשים מתפרסמים על הספינוזאורוס כמעט כל כמה שנים, ותמונתו משתנה איתם: פעם ציירו אותו כמו טירנוזאורוס עם מפרש, אחר כך כמו תנין ענק על ארבע, והיום שוב על שתיים ליד המים. זו דוגמה חיה למדע שממשיך להתעדכן.',
  'ankylosaurus': 'לאנקילוזאורוס היו קרובים רבים, הנקראים אנקילוזאורים. חלקם היו בלי אלה בזנב, ובמקומה קוצים בולטים על הכתפיים. בקנדה נמצא קרוב משוריין שנשמר כל כך טוב, שרואים בו את צורת השריון כמו בפסל — ואפילו שאריות של צבעו.',
  'diplodocus': 'השלד של הדיפלודוקוס שהוצג שנים רבות באולם הכניסה של מוזיאון הטבע בלונדון קיבל כינוי חיבה, ״דיפי״, ויציקות שלו נשלחו למוזיאונים רבים בעולם. בזכותן מיליוני ילדים פגשו דינוזאור בגודל מלא בפעם הראשונה.',
  'brontosaurus': 'במאה ה־19 התחרו שני חוקרים אמריקאים, אותניאל מארש ואדוארד קופ, מי ימצא ויתאר יותר דינוזאורים. בתחרות הזאת, שנקראה ״מלחמת העצמות״, הם מיהרו לתת שמות, ולפעמים נתנו שני שמות לאותה חיה — כך נולד גם הבלבול סביב הברונטוזאורוס.',
  'argentinosaurus': 'בארגנטינה נמצאו גם סאורופודים ענקיים נוספים, כמו פטגוטיטאן, שממנו נמצאו יותר עצמות. היום מתווכחים איזה מהם היה הגדול ביותר, והתשובה עשויה להשתנות עם כל ממצא חדש — ולכן כדאי לומר ״אחד הגדולים ביותר״.',
  'allosaurus': 'האלוזאורוס היה מהטורפים הראשונים שקיבלו תיאור מדעי מלא בצפון אמריקה, כבר במאה ה־19. השם ״לטאה שונה״ ניתן בגלל החוליות שלו, שהיו שונות מאלה של דינוזאורים אחרים שהכירו אז. הוא חי כ־80 מיליון שנה לפני הטירנוזאורוס.',
  'giganotosaurus': 'את השלד הראשון של הגיגנוטוזאורוס מצא חובב מאובנים בפטגוניה שבארגנטינה. ממנו נמצאו עד היום רק שלדים חלקיים, ולכן קשה לקבוע אם היה ארוך או כבד יותר מהטירנוזאורוס. רוב החוקרים אומרים שהיו בערך באותו גודל.',
  'carnotaurus': 'הקרנוטאורוס שייך למשפחה בשם אבליזאורים, טורפים שחיו בעיקר ביבשות הדרום — דרום אמריקה, אפריקה, הודו ומדגסקר. לרבים מהם היו פנים קצרות, בליטות על הראש וזרועות זעירות. הם מילאו שם את התפקיד שמילאו הטירנוזאורים בצפון.',
  'dilophosaurus': 'הדילופוזאורוס חי לפני כ־193 מיליון שנה, כלומר יותר מ־120 מיליון שנה לפני הטירנוזאורוס. הוא אחד הטורפים הגדולים הראשונים של תקופת היורה, ומראה איך הדינוזאורים הטורפים התחילו לגדול אחרי ההכחדה של סוף הטריאס.',
  'coelophysis': 'פעם חשבו שבתוך כמה שלדים של קואלופיזיס יש עצמות של צעירים מאותו מין, וכתבו שהוא אכל את בני מינו. בדיקה חוזרת הראתה שאלה בעיקר עצמות של זוחלים קטנים אחרים. זו דוגמה טובה לכך שגם ״עובדה ידועה״ צריכה לעבור בדיקה חוזרת.',
  'herrerasaurus': 'אזור איסצ׳יגואלסטו מוכר היום כאתר מורשת עולמית בזכות המאובנים שלו. החוקרים מוצאים בו דינוזאורים קדומים לצד זוחלים אחרים מאותה תקופה, וכך יכולים לראות איך נראה העולם בתחילת הדרך של הדינוזאורים — כשהם עוד לא היו השולטים.',
  'eoraptor': 'ליד האאורפטור נמצאו באותו אתר עוד דינוזאורים קדומים, כמו ההררזאורוס. יחד הם מראים שכבר בתחילת דרכם, לפני כ־231 מיליון שנה, הדינוזאורים התחלקו לענפים שונים — טורפים, אוכלי צמחים ואוכלי כל.',
  'plateosaurus': 'בעיירה טרוסינגן שבגרמניה נמצאו שלדים רבים של פלטאוזאורוס במקום אחד. בעבר חשבו שעדר שלם מת שם במדבר, והיום רבים חושבים שבעלי חיים נלכדו בבוץ אחד אחרי השני לאורך זמן — בדומה לבעלי חיים שנתקעים בבוץ גם היום.',
  'iguanodon': 'השלדים מבלגיה הוצבו בתחילה עומדים זקופים כמו קנגורו, עם זנב שנגרר על הקרקע. היום יודעים שהאיגואנודון החזיק את הגב והזנב בקו אופקי, והלך לפעמים על ארבע. כך תיקנו את הטעות השנייה, אחרי הקרן שעל האף.',
  'parasaurolophus': 'לדינוזאורי מקור ברווז אחרים היו ציצות בצורות שונות: עגולה כמו קסדה, קוץ קטן או ציצה מוצקה. ייתכן שכל צורה השמיעה צליל אחר, וכך כל מין ״דיבר״ בקול משלו. זה רעיון מרתק, אבל קשה מאוד להוכיח אותו.',
  'edmontosaurus': 'האדמונטוזאורוס חי בצפון אמריקה עד סוף ימי הדינוזאורים, ומאובניו נמצאו גם באזורים צפוניים מאוד, באלסקה, שם היו חורפים ארוכים וחשוכים. זה מראה שדינוזאורים יכלו לחיות גם במקומות קרים, ואולי נדדו בעונות השונות.',
  'maiasaura': 'הגילוי של המאיאזאורה שינה את התמונה של הדינוזאורים: מ״זוחלים קרי לב״ שמטילים ביצים ועוזבים, להורים שאולי האכילו ושמרו. בעקבותיו התחילו לחפש קינים בכל העולם, ונמצאו עוד עדויות לטיפול בצאצאים.',
  'pachycephalosaurus': 'הפכיצפלוזאורוס חי בסוף הקרטיקון באותו אזור כמו הטירנוזאורוס והטריצרטופס. השיניים שלו היו קטנות ובצורת עלה, ולכן חושבים שאכל בעיקר צמחים, אולי גם פירות וזרעים. הוא הלך על שתי רגליים, כמו רוב הדינוזאורים בעלי הכיפה.',
  'protoceratops': 'במדבר גובי נמצאו גם קינים של פרוטוצרטופס עם גוזלים. מחקר על עוברים בביצים שלו הציע שהקליפה הייתה רכה, כמו של צבים מסוימים — ולא קשה כמו של ציפורים. גם הרעיון הזה עדיין נבדק.',
  'psittacosaurus': 'הפסיטקוזאורוס נקרא כך כבר בשנת 1923. בגלל שיש ממנו כל כך הרבה פרטים, חוקרים בדקו עליו איך דינוזאור עבר מהליכה על ארבע בגיל צעיר להליכה על שתיים כשגדל. כך הוא עוזר להבין גם דינוזאורים אחרים.',
  'deinonychus': 'ליד שלדים של דיינוניכוס נמצאו גם שיניים שלו שנשרו, לצד עצמות של אוכל צמחים גדול. הממצא הזה הוא הבסיס לרעיון שדיינוניכוסים אכלו יחד מטרף אחד. אבל ייתכן גם שהגיעו בנפרד, כמו ציפורים דורסות שמתאספות על פגר.',
  'microraptor': 'המיקרורפטור חי ביערות עם אגמים, בסביבה שבה נשמרו גם ציפורים קדומות, יונקים קטנים וצמחים פורחים. בזכות האפר הגעשי שכיסה את האזור, נשמרו שם פרטים קטנים מאוד — כמו נוצות, תוכן קיבה ואפילו צבעים.',
  'archaeopteryx': 'כל אחת מהדגימות של ארכיאופטריקס קיבלה שם לפי המוזיאון או העיר שבה היא שמורה, כמו ״הדגימה של ברלין״ או ״הדגימה של לונדון״. חלקן נמצאו במחצבות רק אחרי שעובדים הבחינו בטביעה עדינה באבן.',
  'compsognathus': 'השלד של הקומפסוגנתוס נמצא בגרמניה עוד באמצע המאה ה־19, ושלד שני נמצא בצרפת. שניהם כמעט שלמים, וזה נדיר מאוד אצל דינוזאור קטן ועדין. לעצמות דקות כאלה יש סיכוי קטן במיוחד להישמר.',
  'oviraptor': 'לאוביראפטור ולקרוביו היה מקור חזק בלי שיניים, ולכן קשה לדעת בדיוק מה אכלו. הוצעו זרעים, פירות, צדפות, ביצים וחיות קטנות. ייתכן שכל מין במשפחה אכל משהו אחר — כמו אצל ציפורים עם מקורים שונים היום.',
  'therizinosaurus': 'בגלל המראה המוזר שלו — טפרים ענקיים, צוואר ארוך ובטן גדולה — יש מי שקורא לתריזינוזאורוס ״הדינוזאור הכי משונה״. בסין נמצאו קרובים קטנים שלו עם נוצות, ולכן ייתכן שגם הוא היה מכוסה בחלקו בנוצות.',
  'gallimimus': 'הגלימימוס חי באותו אזור כמו הטירנוזאורוס האסייתי, טרבוזאורוס, ובוודאי נאלץ לברוח ממנו. המהירות, הראייה הטובה והחיים בקבוצה היו כנראה הדרכים העיקריות שלו להינצל — כמו של יענים וצבאים היום.',
  'baryonyx': 'השם בריוניקס פירושו ״טופר כבד״, ומתייחס לטופר הגדול שנמצא ראשון. שנים אחר כך התגלו בבריטניה, בפורטוגל ובמקומות אחרים קרובים שלו, ומתברר שמשפחת אוכלי הדגים הזאת הייתה נפוצה הרבה יותר ממה שחשבו.',
  'yutyrannus': 'היוטירנוס הוא הוכחה לכך שבעולם הדינוזאורים, משפחת הטירנוזאורים התחילה מטורפים קטנים יותר, וגדלה עם הזמן. הטירנוזאורוס הענק היה אחד האחרונים במשפחה, אחרי עשרות מיליוני שנים של התפתחות.',
  'pterosaur': 'מאובני פטרוזאורים נדירים, כי העצמות שלהם היו דקות מאוד וחלולות, ונשברו בקלות. רוב המאובנים הטובים נמצאו בסלעים דקי גרגר שנוצרו באגמים ובלגונות, כמו בגרמניה, בברזיל ובסין. שם נשמרו לפעמים אפילו קרומי הכנפיים.',
  'pteranodon': 'הפטרנודון הוא אחד הפטרוזאורים הראשונים שהתגלו בצפון אמריקה, כבר בשנות השבעים של המאה ה־19. נמצאו ממנו מאות פרטים, ולכן הוא אחד הפטרוזאורים המוכרים ביותר — ואחד הנפוצים בצעצועים ובסרטים.',
  'quetzalcoatlus': 'איך יצור ענק כזה המריא? פעם חשבו שהוא רץ כמו מטוס או קפץ מצוקים. היום חוקרים רבים חושבים שהוא נשען על ארבע ו״זינק״ לאוויר בדחיפה חזקה של הזרועות, כמו מקפצה. החישובים עדיין נבדקים.',
  'plesiosaur': 'החוקרים עדיין מתווכחים איך בדיוק השתמשו הפלזיוזאורים בארבעת הסנפירים: האם חתרו בכולם יחד, או בזוג הקדמי בעיקר? בניסויים עם רובוטים שחיים, נמצא שגם הזוג האחורי עזר להאיץ. זו דוגמה למדע שבודק רעיונות בניסוי.',
  'ichthyosaur': 'בשנים האחרונות נמצאו שרידים של איכתיוזאורים ענקיים מתקופת הטריאס, שאולי היו באורך של יותר מעשרים מטרים — בערך כמו לווייתן. גם כאן מדובר בעצמות בודדות, ולכן הגודל הוא הערכה זהירה.',
  'mosasaur': 'המוזאזאורים הופיעו מאוחר יחסית, רק בעשרות מיליוני השנים האחרונות של הקרטיקון, אבל התפשטו מהר לכל ימי העולם. הם נכחדו בהכחדה של סוף הקרטיקון, יחד עם הדינוזאורים הלא־עופיים והפלזיוזאורים.',
  'dimetrodon': 'בין הדימטרודון לבין הדינוזאורים הראשונים עברה ההכחדה הגדולה ביותר בתולדות כדור הארץ, בסוף תקופת הפרם. היא העלימה את רוב היצורים של אותו עולם, ופינתה את הבמה לזוחלים חדשים — ובהם הדינוזאורים.',
  'ammonite': 'אמוניטים קיבלו את שמם מאל מצרי עתיק בשם אמון, שתואר עם קרני איל מסולסלות. לאורך ההיסטוריה אנשים מצאו אותם בכל העולם, ואמרו עליהם שהם נחשים שהפכו לאבן או קרניים של בעלי חיים — עד שהמדע הבין מה הם באמת.',
  'dinosaur': 'בכל שנה מתוארים עשרות מינים חדשים של דינוזאורים, בעיקר מסין, מארגנטינה, מארצות הברית וממונגוליה. לכן הרשימה של ״כל הדינוזאורים״ לעולם לא נגמרת. גם בעתיד, ילדים שקוראים את העמוד הזה עשויים לגלות מין חדש.',
  'fossil': 'מאובנים לא נמצאים רק בסלעים. יצורים נשמרו גם בענבר — שרף עצים שהתקשה — ושם נשמרו חרקים, נוצות ואפילו זנב קטן של דינוזאור עם נוצות. יונקים מתקופת הקרח נשמרו בקרח ובבוץ קפוא, אבל אלה צעירים בהרבה מהדינוזאורים.',
  'paleontologist': 'בעבודה של פלאונטולוג יש הרבה סבלנות: חודשים בשטח בחום או בקור, ושנים של עבודה במעבדה. אבל יש בה גם רגעים מרגשים מאוד — כמו הרגע שבו רואים לראשונה עצם שאף אדם לא ראה לפניכם, ממין שאף אחד לא הכיר.',
  'mesozoic': 'כדי לזכור את סדר שלוש התקופות, אפשר לחשוב על משפט כמו ״טלי יוצאת קודם״: טריאס, יורה, קרטיקון. המזוזואיקון כולו נמשך כ־186 מיליון שנה — פי מאות מכל ההיסטוריה של בני האדם.',
  'triassic': 'בטריאס חיו לצד הדינוזאורים זוחלים רבים אחרים: קרובים קדומים של התנינים, חלקם גדולים וטורפים, זוחלים צמחוניים עם מקור, והאיכתיוזאורים הראשונים בים. בסוף התקופה רבים מהם נעלמו בהכחדה, והדינוזאורים התפשטו במקומם.',
  'jurassic': 'ביורה הופיעו גם צפרדעים וסלמנדרות שדומות לאלה של היום, ויונקים קטנים חיו בשולי היערות. בים שחו פלזיוזאורים ואיכתיוזאורים, ובשמיים עפו פטרוזאורים. זה היה עולם עשיר, עם אקלים חמים בהרבה מהיום.',
  'cretaceous': 'בקרטיקון חיו גם צבים, תנינים, לטאות, נחשים קדומים, יונקים קטנים וציפורים רבות. על הים שלטו המוזאזאורים, ובשמיים — הפטרוזאורים הענקיים. היו גם חרקים מאביקים, כמו דבורים, שהתפתחו לצד הפרחים.',
  'pangaea': 'את הרעיון שהיבשות זזות הציע המדען אלפרד וגנר בתחילת המאה ה־20, אבל רבים לא האמינו לו כי לא היה ברור מה מזיז אותן. רק בשנות השישים התגלה שהקרקעית של האוקיינוסים מתרחבת, והרעיון התקבל.',
  'theropod': 'הדרך הכי קלה לזהות עקבה של תרופוד היא לפי שלוש אצבעות צרות עם סימני טפרים. עקבות כאלה נמצאו בעולם כולו, וגם בבית זית שליד ירושלים. לפעמים נמצאות שורות ארוכות שלהן, שמספרות על דינוזאור שהלך לאורך חוף.',
  'sauropod': 'הצאצאים הענקיים של הסאורופודים לא היו הראשונים בקבוצה: האבות הקדומים שלהם בטריאס, כמו הפלטאוזאורוס, היו קטנים יותר והלכו כנראה על שתיים. במשך מיליוני שנים הם גדלו שוב ושוב, עד הענקים של היורה והקרטיקון.',
  'hip-groups': 'קל לזכור כך: ״אגן לטאה״ — הטורפים וענקי הצוואר; ״אגן ציפור״ — אוכלי הצמחים עם המקור. ובהערת שוליים: הציפורים דווקא בקבוצה הראשונה. השמות נקבעו במאה ה־19, לפני שהבינו את הקשר בין דינוזאורים לציפורים.',
  'hadrosaur': 'ההדרוזאורים הראשונים שנמצאו בצפון אמריקה תוארו כבר באמצע המאה ה־19, ואחד מהם היה מהשלדים הראשונים של דינוזאור שהוצגו במוזיאון. מאז נמצאו מהם עשרות סוגים, באמריקה, באסיה ובאירופה.',
  'ceratopsian': 'רוב הצרטופסים חיו באסיה ובצפון אמריקה, שהיו מחוברות לפעמים בגשר יבשתי. המינים הקדומים נמצאו בעיקר בסין ובמונגוליה, והגדולים והמאוחרים — בעיקר בצפון אמריקה. כך אפשר לראות איך המשפחה ״נדדה״ ביבשות.',
  'coprolite': 'קופרוליטים נמצאים גם מבעלי חיים רבים אחרים, כמו כרישים, דגים ותנינים. אספנים אוהבים אותם בגלל הצורות המצחיקות, והמדענים — בגלל המידע. בחלק מהם נמצאו אפילו שרידים של טפילים זעירים שחיו במעיים.',
  'dinosaur-footprints': 'יש אתרים בעולם שבהם אלפי עקבות דינוזאורים נמצאים על משטח סלע אחד, כמו רצפה ענקית. בחלק מהם אפשר לראות עקבות של טורף והולכים לצידו עקבות של אוכל צמחים. חוקרים מתווכחים אם זה רגע של מרדף או סתם שני מעברים בזמנים שונים.',
  'gastroliths': 'קשה לזהות גסטרוליט: אבן מלוטשת יכולה להיות מלוטשת גם בנהר או בחוף. לכן החוקרים מחשיבים אבן כגסטרוליט רק כשהיא נמצאת בתוך השלד, במקום הקיבה, ולא סתם ליד העצמות.',
  'dinosaur-feathers': 'נוצות לא נשמרות בקלות, ולכן ייתכן שהיו נפוצות יותר ממה שאנחנו יודעים. מצד שני, כשנמצאות טביעות עור עם קשקשים, זו עדות טובה שבאותו חלק של הגוף לא היו נוצות. התמונה המלאה עוד נבנית.',
  'mass-extinction': 'הכחדה המונית לא קורית ביום אחד בכל העולם. לפעמים היא נמשכת אלפי שנים ואף יותר. גם אחריה, לוקח לעולם החי מיליוני שנים להתאושש ולהתמלא מחדש במינים חדשים.',
  'chicxulub-crater': 'אחד הסימנים המפתיעים לפגיעה נמצא רחוק מאוד: בדקוטה הצפונית שבארצות הברית נמצא אתר שבו דגים נקברו עם כדוריות זכוכית זעירות שנפלו מהשמיים אחרי הפגיעה. חוקרים מעריכים שזה קרה כבר בשעות הראשונות.',
  'radiometric-dating': 'השיטות האלה נבדקות שוב ושוב: מודדים את אותה שכבה בכמה שיטות שונות, ובכמה מעבדות בעולם. כשהתוצאות מתאימות זו לזו, החוקרים בטוחים יותר. כך קבעו שגיל ההכחדה הוא כ־66 מיליון שנה.',
  'mary-anning': 'ליד ליים רג׳יס נמצא היום חוף שנקרא ״חוף היורה״, ומבקרים מגיעים אליו כדי לחפש מאובנים בבטחה בשפל ולא ליד המצוקים. לכבודה של מרי אנינג הוקם בעיירה פסל שלה, והוצאו ספרים וסרטים על חייה.',
  'dinosaur-eggs': 'ביצי דינוזאורים נמצאות לפעמים בשורות או במעגלים, לפי הדרך שבה ההורה הטיל אותן. אצל קרובי האוביראפטור, למשל, הביצים מסודרות בזוגות במעגל, וההורה ישב באמצע — סידור שעזר לחמם את כולן.',
  'dinosaurs-sea-israel': 'גם היום אפשר לראות סימנים לים הקדום: בשכבות הסלע בנגב יש פוספטים, שנוצרו מהצטברות של שרידי יצורי ים, ובהם נמצאים לא פעם שיניים של כרישים ועצמות של דגים וזוחלים. זה ארכיון שלם שנשמר באדמה של ישראל.'
}

